resource "aws_s3_bucket_lifecycle_configuration" "nexus-apollo-data" {
  bucket = aws_s3_bucket.nexus-apollo-data.id
  rule {
    id     = "expire-objects"
    filter {
      prefix = ""
    }
    expiration {
      days = 30
    }
  }
}

resource "aws_security_group" "nexus-apollo-data" {
  name        = "nexus-apollo-data-sg"
  description = "Security group for nexus-apollo-data"
  vpc_id      = aws_vpc.nexus-apollo-data.id
}
